<?php
declare(strict_types=1);require_once __DIR__.'/../../includes/lacms_sync_helpers.php';requireLacmsPermission('lacms.sync.view');$pdo=db();$id=(int)($_GET['id']??0);$s=lacmsSyncContext($pdo,$id);if(!$s)exit('Coordination record not found.');$q=$pdo->prepare("SELECT a.*,u.full_name responsible_name,o.name office_name FROM lacms_sync_actions a LEFT JOIN users u ON u.id=a.responsible_user_id LEFT JOIN offices o ON o.id=a.responsible_office_id WHERE a.sync_record_id=:id ORDER BY a.id");$q->execute([':id'=>$id]);$actions=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title><?= e($s['sync_reference']) ?></title><style>body{font:12px Arial;margin:28px;color:#111827}.head{text-align:center;border-bottom:3px solid #0f2137;padding-bottom:12px}.box{border:1px solid #ccc;padding:9px;margin:10px 0}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccc;padding:6px}th{background:#eee}</style></head><body onload="window.print()"><div class="head"><strong><?= e(APP_NAME) ?></strong><h2>Executive-Legislative Synchronization Record</h2><div><?= e($s['sync_reference']) ?></div></div><h3><?= e($s['title']) ?></h3><div class="box"><strong>Type:</strong> <?= e($s['sync_type']) ?><br><strong>Priority:</strong> <?= e($s['priority_level']) ?><br><strong>Status:</strong> <?= e($s['status']) ?><br><strong>Executive Office:</strong> <?= e($s['source_office_name']?:'—') ?><br><strong>Legislative Committee:</strong> <?= e($s['target_committee_name']?:'—') ?><br><br><strong>Executive Position</strong><br><?= nl2br(e($s['executive_position']?:'—')) ?><br><br><strong>Legislative Position</strong><br><?= nl2br(e($s['legislative_position']?:'—')) ?><br><br><strong>Resolution Notes</strong><br><?= nl2br(e($s['resolution_notes']?:'—')) ?></div><h3>Coordination Actions</h3><table><thead><tr><th>Action</th><th>Responsible</th><th>Due</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php foreach($actions as $a): ?><tr><td><?= e($a['action_title']) ?></td><td><?= e($a['responsible_name']?:$a['office_name']?:'—') ?></td><td><?= $a['due_datetime']?formatDateTime($a['due_datetime']):'—' ?></td><td><?= e($a['priority_level']) ?></td><td><?= e($a['status']) ?></td></tr><?php endforeach; ?></tbody></table></body></html>
